// Rule-based fixer: cleans the Tailwind markup generated by the Figma plugin. No AI involved.
const SPACING = { 0: '0', 1: 'px', 2: '0.5', 4: '1', 6: '1.5', 8: '2', 10: '2.5', 12: '3', 14: '3.5', 16: '4', 20: '5', 24: '6', 28: '7', 32: '8', 36: '9', 40: '10', 44: '11', 48: '12', 56: '14', 64: '16', 80: '20', 96: '24', 112: '28', 128: '32', 144: '36', 160: '40', 176: '44', 192: '48', 208: '52', 224: '56', 240: '60', 256: '64', 288: '72', 320: '80', 384: '96' };
const TEXT = { 12: 'xs', 14: 'sm', 16: 'base', 18: 'lg', 20: 'xl', 24: '2xl', 30: '3xl', 36: '4xl', 48: '5xl', 60: '6xl', 72: '7xl', 96: '8xl', 128: '9xl' };
const RADIUS = { 2: '-sm', 4: '', 6: '-md', 8: '-lg', 12: '-xl', 16: '-2xl', 24: '-3xl' };
const OPACITY = new Set([0, 5, 10, 20, 25, 30, 40, 50, 60, 70, 75, 80, 90, 95, 100]);
const BORDER_W = { 0: '-0', 1: '', 2: '-2', 4: '-4', 8: '-8' };

const SPACING_PRE = '(?:p|px|py|pt|pr|pb|pl|m|mx|my|mt|mr|mb|ml|gap|gap-x|gap-y|w|h|min-w|min-h|top|right|bottom|left|inset|inset-x|inset-y)';
const RE_SPACE = new RegExp(`^(-?)(${SPACING_PRE})-\\[(-?\\d+(?:\\.\\d+)?)px\\]$`);
const RE_TEXT = /^text-\[(\d+(?:\.\d+)?)px\]$/;
const RE_ROUND = /^rounded((?:-(?:t|r|b|l|tl|tr|br|bl))?)-\[(\d+(?:\.\d+)?)px\]$/;
const RE_OPACITY = /^opacity-\[(\d*\.?\d+)\]$/;
const RE_BORDER = /^border((?:-(?:t|r|b|l|x|y))?)-\[(\d+(?:\.\d+)?)px\]$/;
const RE_COLOR = /^(bg|text|border|outline|fill|stroke)-\[#(?:ffffff|fff)\]$/i;
const RE_COLOR_BLACK = /^(bg|text|border|outline|fill|stroke)-\[#(?:000000|000)\]$/i;
const RE_PCT = /^(w|h)-\[100%\]$/;

function normalize(token, ctx) {
  const i = token.lastIndexOf(':');
  const v = i >= 0 ? token.slice(0, i + 1) : '';
  const t = i >= 0 ? token.slice(i + 1) : token;
  let m, out = t;

  if ((m = t.match(RE_SPACE))) {
    const key = parseFloat(m[3]);
    const abs = Math.abs(key);
    const neg = (m[1] === '-') !== (key < 0);
    if (SPACING[abs] !== undefined) out = `${neg && abs ? '-' : ''}${m[2]}-${SPACING[abs]}`;
  } else if ((m = t.match(RE_TEXT))) {
    // text-xs etc. also set a line-height, so only convert when an explicit leading-* exists
    if (TEXT[+m[1]] && ctx.hasLeading) out = `text-${TEXT[+m[1]]}`;
  } else if ((m = t.match(RE_ROUND))) {
    const px = +m[2];
    if (px >= 999) out = `rounded${m[1]}-full`;
    else if (RADIUS[px] !== undefined) out = `rounded${m[1]}${RADIUS[px]}`;
  } else if ((m = t.match(RE_OPACITY))) {
    const pct = Math.round(parseFloat(m[1]) * 100);
    if (OPACITY.has(pct) && Math.abs(pct / 100 - parseFloat(m[1])) < 0.001) out = `opacity-${pct}`;
  } else if ((m = t.match(RE_BORDER))) {
    if (BORDER_W[+m[2]] !== undefined) out = `border${m[1]}${BORDER_W[+m[2]]}`;
  } else if ((m = t.match(RE_COLOR))) out = `${m[1]}-white`;
  else if ((m = t.match(RE_COLOR_BLACK))) out = `${m[1]}-black`;
  else if ((m = t.match(RE_PCT))) out = `${m[1]}-full`;

  if (out !== t) ctx.stats.converted++;
  return v + out;
}

function fixClassList(list, stats) {
  const raw = list.split(/\s+/).filter(Boolean);
  const ctx = { stats, hasLeading: raw.some((t) => /(^|:)leading-/.test(t)) };
  const seen = new Set();
  const out = [];
  for (const tok of raw) {
    const n = normalize(tok, ctx);
    if (seen.has(n)) { stats.duplicates++; continue; }
    seen.add(n);
    out.push(n);
  }
  // drop "md:gap-4" when base "gap-4" is identical (no-op responsive variant)
  return out.filter((t) => {
    const m = t.match(/^(?:sm|md|lg|xl|2xl):(.+)$/);
    if (m && seen.has(m[1])) { stats.redundantVariants++; return false; }
    return true;
  });
}

function fixHtml(html) {
  const stats = { converted: 0, duplicates: 0, redundantVariants: 0, buttons: 0, icons: 0 };
  let out = html.replace(/\bclass="([^"]*)"/g, (_, list) => `class="${fixClassList(list, stats).join(' ')}"`);
  // <button> without type submits forms by accident
  out = out.replace(/<button(?![^>]*\btype=)([^>]*)>/g, (_, rest) => { stats.buttons++; return `<button type="button"${rest}>`; });
  // decorative icons: hide from screen readers
  out = out.replace(/<svg class="block w-full h-full"(?![^>]*aria-hidden)>/g, () => { stats.icons++; return '<svg class="block w-full h-full" aria-hidden="true" focusable="false">'; });
  stats.total = stats.converted + stats.duplicates + stats.redundantVariants + stats.buttons + stats.icons;
  return { html: out, stats };
}

module.exports = { fixHtml, fixClassList };
